/*
 * A226136  Positions of the positive integers in the ordering of rational
 *          numbers as generated by the rules: 1 is in S, and if nonzero x is
 *          in S, then x+1 and -1/x are in S. (See Comments.)
 * https://oeis.org/A226136
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = a(n-1)+a(n-3) for n>6; a(1)=1, a(2)=2, a(3)=4, a(4)=7,
 *            a(5)=10, a(6)=15
 * Range:     u8 n <= 13, u16 n <= 27, u32 n <= 36, u64 n <= 36, u128 n <= 36,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    if (n < 1) return (seq_t)0;   /* undefined for n<1, return 0 */

    /* static cache of previously computed terms */
    static seq_t *cache = NULL;
    static idx_t cache_size = 0; /* number of terms stored (>=0) */
    static idx_t cache_cap  = 0; /* allocated capacity, 0 means not yet allocated */

    /* ensure enough capacity for 1‑based indexing */
    if (n > cache_cap) {
        idx_t new_cap = (cache_cap == 0) ? 16 : cache_cap;
        while (new_cap < n) new_cap <<= 1;
        /* realloc to size (new_cap+1) to use 1‑based indexing */
        cache = (seq_t *)realloc(cache, (new_cap + 1) * sizeof(seq_t));
        cache_cap = new_cap;
    }

    /* pre‑computed initial values */
    static const seq_t init[7] = { (seq_t)0, (seq_t)1, (seq_t)2, (seq_t)4,
                                   (seq_t)7, (seq_t)10, (seq_t)15 };

    /* compute missing terms up to n */
    for (idx_t i = cache_size + 1; i <= n; ++i) {
        if (i <= 6) {
            cache[i] = init[i];
        } else {
            cache[i] = cache[i - 1] + cache[i - 3];
        }
    }
    cache_size = n;

    return cache[n];
}
